body.script:
function icone(t, id) {
  const c = document.createElement('canvas');
  c.width = c.height = t;
  const x = c.getContext('2d');
  x.fillStyle = '#0a7d3b';
  x.fillRect(0, 0, t, t);
  x.fillStyle = '#fff';
  x.font = 'bold ' + t * 0.28 + 'px sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText('FCFA', t / 2, t / 2);
  document.getElementById(id).href = c.toDataURL('image/png');
}
icone(192, 'a192');
icone(512, 'a512');
